def questions_to_chats(apps, schema_editor):
    """Pertanyaan lama (Tanya Kami) menjadi obrolan: pertanyaan = pesan pelanggan, jawaban = pesan admin.

    Yang sudah dijawab menjadi obrolan Selesai (tetap bisa dilihat di riwayat).
    """
    Question = apps.get_model("members", "Question")
    Conversation = apps.get_model("members", "Conversation")
    ChatMessage = apps.get_model("members", "ChatMessage")
    for q in Question.objects.all().order_by("created_at"):
        answered = bool((q.answer or "").strip())
        last_at = q.answered_at or q.created_at
        conv = Conversation.objects.create(
            member_id=q.member_id, topic=q.topic, created_at=q.created_at,
            status="selesai" if answered else "terbuka", closed_at=last_at if answered else None,
            last_message_at=last_at, last_sender="admin" if answered else "pelanggan",
            member_read_at=None, admin_read_at=last_at,
        )
        ChatMessage.objects.create(conversation=conv, sender="pelanggan", text=q.message, created_at=q.created_at)
        if answered:
            ChatMessage.objects.create(conversation=conv, sender="admin", text=q.answer, created_at=last_at)


def fill_order_amount(apps, schema_editor):
    Order = apps.get_model("members", "Order")
    for order in Order.objects.filter(amount__isnull=True).exclude(package=None).select_related("package"):
        order.amount = order.package.price
        order.save(update_fields=["amount"])


